<?php require APPROOT.'/views/inc/header.php'; ?><div class="app-content"><div class="container-fluid py-4"><div class="d-flex justify-content-between align-items-start"><div><h1 class="h3">Cierres de asistencia</h1><p class="text-secondary">Paquetes mensuales informativos, congelados y trazables.</p></div><form><input class="form-control" type="month" name="month" value="<?= htmlspecialchars($month) ?>" onchange="this.form.submit()"></form></div><?php if(!empty($_SESSION['flash_error'])):?><div class="alert alert-danger"><?= htmlspecialchars($_SESSION['flash_error']);unset($_SESSION['flash_error']);?></div><?php endif;?><?php if(!empty($_SESSION['flash_success'])):?><div class="alert alert-success"><?= htmlspecialchars($_SESSION['flash_success']);unset($_SESSION['flash_success']);?></div><?php endif;?><div class="card border-0 shadow-sm mb-4"><div class="card-body"><div class="d-flex justify-content-between"><div><h2 class="h5">Vista previa · <?= htmlspecialchars($month) ?></h2><span class="text-secondary"><?= count($preview) ?> empleados</span></div><form method="post" action="<?= URLROOT ?>/admin/prepareAttendanceClosure"><?= csrf_field() ?><input type="hidden" name="month" value="<?= htmlspecialchars($month) ?>"><button class="btn btn-primary">Preparar nueva versión</button></form></div></div></div><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Período</th><th>Versión</th><th>Estado</th><th>Preparado</th><th>Hash</th><th>Acciones</th></tr></thead><tbody><?php foreach($closures as $c):?><tr><td><?= htmlspecialchars($c->period_month) ?></td><td><?= (int)$c->version_no ?></td><td><span class="badge text-bg-<?= $c->status==='closed'?'success':($c->status==='reopened'?'warning':'secondary') ?>"><?= htmlspecialchars($c->status) ?></span></td><td><?= htmlspecialchars($c->prepared_name??'') ?></td><td><code><?= htmlspecialchars(substr($c->snapshot_hash??'',0,12)) ?>…</code></td><td><div class="d-flex flex-wrap gap-1"><a class="btn btn-sm btn-outline-secondary" href="<?= URLROOT ?>/admin/exportAttendanceClosureCsv/<?= (int)$c->id ?>">CSV</a><a class="btn btn-sm btn-outline-secondary" href="<?= URLROOT ?>/admin/exportAttendanceClosurePdf/<?= (int)$c->id ?>">PDF</a><?php if($c->status==='draft'):?><form method="post" action="<?= URLROOT ?>/admin/closeAttendanceClosure/<?= (int)$c->id ?>"><?= csrf_field() ?><button class="btn btn-sm btn-success">Cerrar</button></form><?php elseif($c->status==='closed'):?><form class="d-flex" method="post" action="<?= URLROOT ?>/admin/reopenAttendanceClosure/<?= (int)$c->id ?>"><?= csrf_field() ?><input class="form-control form-control-sm" name="reason" placeholder="Motivo" required><button class="btn btn-sm btn-warning">Reabrir</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></div></div></div><?php require APPROOT.'/views/inc/footer.php'; ?>
